"""Canonical date-scoped identities1600–1699; original source shapes unchanged."""
import pathlib,json
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'public/data'
read=lambda f:json.loads((OUT/f).read_text(encoding='utf8'))
def prepare(ids):
 cs=ids['countries'];d=dict(format='dated-entity-resolution',coverageStart=1600,coverageEnd=1699,referenceDate='2026-10-26',qidKeys={},names={k:c['name'] for k,c in cs.items()},records=[])
 for k,c in cs.items():
  if c.get('qid'):d['qidKeys'].setdefault(c['qid'],k)
 for k in ['MING','SOUTHERN-MING','LATER-JIN','QING','JOS','RUSSIA-TSARDOM','BAVARIA-DUCHY','BAVARIA-ELECTORATE','SAXONY-ELECTORATE','ELECTORATE-BRANDENBURG','PRUSSIA-DUCHY','ENGLISH-COMMONWEALTH','IBERIAN-UNION','SAADI','DUTCH-REPUBLIC','POLISH-LITHUANIAN','HABSBURG-MONARCHY']:
  d['qidKeys'][cs[k]['qid']]=k
 def rule(names,key,a=1600,b=1699,label=None,admin='',status='independent',note=''):
  d['records'].append(dict(names=names.split('|'),key=key,label=label or cs[key]['name'],entityCode=key,start=a,end=b,admin=admin,status=status,source='https://github.com/AlejandroPico/Historicmap/blob/main/docs/RESEARCH-1600.md',note=note+' Geometría anual de síntesis, sin frontera diaria acreditada.'))
 rule('Holy Roman Empire|Holy Roman Empire Minor States','HIST-Q12548',label='Estados agrupados del Sacro Imperio',note='Múltiples soberanías territoriales. El emperador no es un jefe de Estado nacional único de todos los miembros; no se inventan límites individuales.')
 rule('Habsburg Monarchy','HABSBURG-MONARCHY',note='Se rechaza el identificador de desambiguaciónQ66504140; varias ramas y cesiones dinásticas requieren detalle regional.')
 rule('Duchy of Bavaria','BAVARIA-DUCHY',b=1622)
 rule('Duchy of Bavaria|Electorate of Bavaria','BAVARIA-ELECTORATE',a=1623)
 rule('Electorate of Saxony','SAXONY-ELECTORATE')
 rule('Electorate of Brandenburg|Brandenburg-Prussia','ELECTORATE-BRANDENBURG',b=1617)
 rule('Electorate of Brandenburg|Brandenburg-Prussia|Duchy of Prussia','HIST-Q157367',a=1618,label='Brandeburgo-Prusia · unión dinástica')
 rule('Duchy of Prussia','PRUSSIA-DUCHY',b=1617)
 rule('House of Savoy|Duchy of Savoy','SAVOY-DUCHY')
 rule('Republic of Florence|Grand Duchy of Tuscany','HIST-Q154849',label='Gran Ducado de Toscana',note='La etiqueta republicana medieval de la fuente no prolonga el régimen después de1569.')
 rule('Papal States|Comtat Venaissin','PAPAL-STATES')
 rule('Republic of Venice','HIST-Q4948',label='República de Venecia')
 rule('Republic of Genoa','HIST-Q174306',label='República de Génova')
 rule('Republic of Ragusa','HIST-Q208169',label='República de Ragusa')
 rule('Kingdom of France','FRA',label='Francia · monarquía borbónica')
 rule('Kingdom of Spain|Spanish Empire','ESP',label='Monarquía hispánica')
 rule('Iberian Union','IBERIAN-UNION',b=1639,note='Unión dinástica de coronas, no anexión dePortugal a una administración española única.')
 rule('Iberian Union','ESP',a=1640,label='Monarquía hispánica · fuente tras la Restauración portuguesa',note='La independencia portuguesa se restablece en1640. Si persiste un agregado anterior, no acredita que continúe la unión ni permite separar un contorno inexistente.')
 rule('Kingdom of Portugal|Portuguese Empire','PRT',label='Monarquía portuguesa')
 rule('Portuguese Colonies','HIST-Q200464',admin='PRT',status='colony',note='Los soberanos portugueses de la unión ibérica se documentan enPortugal; no se prolongan losBraganza antes de1640.')
 rule('Portuguese Ceylon','HIST-Q1709007',admin='PRT',status='colony',label='Ceilán portugués')
 rule('New France','HIST-Q170604',admin='FRA',status='colony',label='Nueva Francia')
 rule('French India','HIST-Q646374',a=1664,admin='FRA',status='company-rule',label='Establecimientos franceses enIndia')
 rule('New Sweden','HIST-Q322187',a=1638,b=1655,admin='SWE',status='colony',label='Nueva Suecia')
 rule('New Netherland','HIST-Q382593',b=1663,admin='DUTCH-REPUBLIC',status='colony',label='Nueva Neerlandia')
 rule('New Netherland','HIST-Q382593',a=1664,b=1672,admin='ENGLAND',status='colony',label='Nueva York · administración inglesa')
 rule('New Netherland','HIST-Q382593',a=1673,b=1673,admin='DUTCH-REPUBLIC',status='colony',label='Nueva Orange · restitución neerlandesa')
 rule('New Netherland','HIST-Q382593',a=1674,admin='ENGLAND',status='colony',label='Nueva York · administración inglesa')
 rule('Dutch Republic','DUTCH-REPUBLIC')
 for name,key in [('Dutch Cape Colony','HIST-Q4807130'),('Dutch Ceylon','HIST-Q1841483'),('Dutch Gold Coast','HIST-Q770776')]:rule(name,key,admin='DUTCH-REPUBLIC',status='colony',note='Autoridades de laRepública separadas de los gobiernos de compañías y administraciones locales todavía parciales.')
 rule('English Colonial Empire|British Colonial Empire','ENGLISH-COLONIES',b=1648,admin='ENGLAND',status='colony')
 rule('English Colonial Empire|British Colonial Empire','ENGLISH-COLONIES',a=1649,b=1659,admin='ENGLISH-COMMONWEALTH',status='colony')
 rule('English Colonial Empire|British Colonial Empire','ENGLISH-COLONIES',a=1660,admin='ENGLAND',status='colony')
 rule('Kingdom of England|Commonwealth of England','ENGLAND',b=1648)
 rule('Kingdom of England|Commonwealth of England','ENGLISH-COMMONWEALTH',a=1649,b=1659)
 rule('Kingdom of England|Commonwealth of England','ENGLAND',a=1660)
 rule('Kingdom of Scotland','SCOTLAND',b=1651)
 rule('Kingdom of Scotland','ENGLISH-COMMONWEALTH',a=1652,b=1659,note='Incorporación al régimen republicano inglés; no se le atribuye una monarquía restaurada antes de1660.')
 rule('Kingdom of Scotland','SCOTLAND',a=1660)
 rule('Denmark-Norway','DENMARK-NORWAY')
 rule('Kingdom of Sweden|Swedish Empire','SWE',label='Reino de Suecia')
 rule('Tsardom of Russia','RUSSIA-TSARDOM')
 rule('Polish-Lithuanian Commonwealth','POLISH-LITHUANIAN')
 rule('Ottoman Empire','OTT')
 rule('Saadi Sultanate|Morocco','SAADI',b=1658,note='La crisis y los poderes regionales posteriores no se convierten en sucesión alauí automática.')
 rule('Saadi Sultanate|Morocco','SAADI',a=1659,b=1665,label='Marruecos · poderes regionales y sucesión disputada',status='source-reference')
 rule('Saadi Sultanate|Morocco','MAR',a=1666,label='Marruecos · dinastía alauí')
 rule('Safavid Dynasty|Safavid dynasty','SAFAVID')
 rule('Ming Dynasty|Ming dynasty','MING')
 rule('Southern Ming','SOUTHERN-MING')
 rule('Later Jin Dynasty','LATER-JIN',a=1616,b=1635)
 rule('Later Jin Dynasty|Qing Dynasty','QING',a=1636,label='Imperio de la dinastía Qing')
 rule('Li Zicheng','SHUN',a=1644,b=1645,note='El QID original es una persona. La entidad política correcta es la dinastíaShunQ2370784, con control y continuidad distintos deMing yQing.')
 rule('Joseon','JOS',note='Entidad correctaQ28179; noGojoseon antiguoQ28405.')
 rule('Tokugawa Shogunate|Warring States Japan','JPN',b=1602,label='Japón · transición al gobierno Tokugawa',note='La victoria deSekigahara y el nombramiento shogunal de1603 son hechos distintos. La cronología de la fuente no los convierte en un solo evento.')
 rule('Tokugawa Shogunate|Warring States Japan','JPN',a=1603,label='Japón · shogunato Tokugawa')
 rule('Ayutthaya Kingdom','AYUTTHAYA')
 rule('Khmer Empire','KHM',label='Reino de Camboya',note='La denominación imperial medieval de la fuente no acredita el régimen del sigloXVII.')
 rule('Kingdom of Bhutan','BTN',a=1616,label='Bután · gobierno dual')
 rule('Gorkha Kingdom','HIST-Q3332217',label='Reino de Gorkha')
 for name,key in [('Eastern Moghulistan','EASTERN-MOGHULISTAN'),('Western Moghulistan','WESTERN-MOGHULISTAN')]:rule(name,key,status='source-reference',note='La fuente comparte unQID para dos ámbitos diferentes. Se conservan identidades locales separadas y no se les asigna automáticamente el mismo khan; la serie regional está pendiente.')
 rule('County of Urgell','ESP',label='Urgell · monarquía hispánica',note='El condado independiente terminó en1413. La persistencia de la etiqueta no acredita un Estado soberano en1600.')
 rule('Sultanate of Malacca','HIST-Q46652',b=1640,admin='PRT',status='colony',label='Malaca · administración portuguesa',note='No se prolonga el sultanato independiente posterior a la conquista de1511.')
 rule('Sultanate of Malacca','HIST-Q46652',a=1641,admin='DUTCH-REPUBLIC',status='company-rule',label='Malaca · administración neerlandesa',note='Cambio de1641; los cargos republicanos se distinguen de los representantes de laVOC.')
 return d
if __name__=='__main__':
 d=prepare(read('identities.json'));(OUT/'historical-1600-entities.json').write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n');print('Dated rules',len(d['records']))
